237	  public static class AuthorColumnInfo extends VcsColumnInfo<String> {
238	    private final TableCellRenderer AUTHOR_RENDERER = new AuthorCellRenderer();
239	
240	    public AuthorColumnInfo() {
241	      super(VcsBundle.message("column.name.revision.list.author"));
242	    }
243	
244	    protected String getDataOf(VcsFileRevision object) {
245	      VcsFileRevision rev = object;
246	      if (object instanceof TreeNodeOnVcsRevision) {
247	        rev = ((TreeNodeOnVcsRevision)object).getRevision();
248	      }
249	
250	      if (rev instanceof VcsFileRevisionEx) {
251	        if (!rev.getAuthor().equals(((VcsFileRevisionEx)rev).getCommitterName())) return object.getAuthor() + "*";
252	      }
253	
254	      return object.getAuthor();
255	    }
256	
257	    @Override
258	    public TableCellRenderer getRenderer(VcsFileRevision revision) {
259	      return AUTHOR_RENDERER;
260	    }
261	
262	    @Override
263	    public TableCellRenderer getCustomizedRenderer(VcsFileRevision value, TableCellRenderer renderer) {
264	      if (renderer instanceof AuthorCellRenderer) {
265	        VcsFileRevision revision = value;
266	        if (value instanceof TreeNodeOnVcsRevision) {
267	          revision = ((TreeNodeOnVcsRevision)value).getRevision();
268	        }
269	
270	        if (revision instanceof VcsFileRevisionEx) {
271	          final VcsFileRevisionEx ex = (VcsFileRevisionEx)revision;
272	          final StringBuilder sb = new StringBuilder(ex.getAuthor());
273	          if (ex.getAuthorEmail() != null) sb.append(" &lt;").append(ex.getAuthorEmail()).append("&gt;");
274	          if (ex.getCommitterName() != null && !ex.getAuthor().equals(ex.getCommitterName())) {
275	            sb.append(", via ").append(ex.getCommitterName());
276	            if (ex.getCommitterEmail() != null) sb.append(" &lt;").append(ex.getCommitterEmail()).append("&gt;");
277	          }
278	          ((AuthorCellRenderer)renderer).setTooltipText(sb.toString());
279	        }
280	      }
281	
282	      return renderer;
283	    }
284	
285	    @Override
286	    @NonNls
287	    public String getPreferredStringValue() {
288	      return "author_author";
289	    }
