346	  public FileHistoryPanelImpl(AbstractVcs vcs,
347	                              @NotNull FilePath filePath,
348	                              @Nullable VcsRevisionNumber startingRevision,
349	                              VcsHistorySession session,
350	                              VcsHistoryProvider provider,
351	                              ContentManager contentManager,
352	                              @NotNull FileHistoryRefresherI refresherI,
353	                              final boolean isStaticEmbedded) {
354	    super(contentManager, provider.getHelpId() != null ? provider.getHelpId() : "reference.versionControl.toolwindow.history", ! isStaticEmbedded);
355	    myProject = vcs.getProject();
356	    myIsStaticAndEmbedded = false;
357	    myVcs = vcs;
358	    myProvider = provider;
359	    myAnnotationProvider = myVcs.getCachingAnnotationProvider();
360	    myRefresherI = refresherI;
361	    myHistorySession = session;
362	    myFilePath = filePath;
363	    myStartingRevision = startingRevision;
364	
365	    DiffFromHistoryHandler customDiffHandler = provider.getHistoryDiffHandler();
366	    myDiffHandler = customDiffHandler == null ? new StandardDiffFromHistoryHandler() : customDiffHandler;
367	
368	    final DualViewColumnInfo[] columns = createColumnList(myVcs.getProject(), provider, session);
369	
370	    myComments = new JEditorPane(UIUtil.HTML_MIME, "");
371	    myComments.setPreferredSize(new Dimension(150, 100));
372	    myComments.setEditable(false);
373	    myComments.setBackground(UIUtil.getComboBoxDisabledBackground());
374	    myComments.addHyperlinkListener(BrowserHyperlinkListener.INSTANCE);
375	
376	    myRevisionsOrder = new HashMap<VcsRevisionNumber, Integer>();
377	    refreshRevisionsOrder();
378	
379	    replaceTransferable();
380	
381	    myUpdateAlarm = new Alarm(Alarm.ThreadToUse.POOLED_THREAD, myProject);
382	
383	    final HistoryAsTreeProvider treeHistoryProvider = myHistorySession.getHistoryAsTreeProvider();
384	
385	    @NonNls String storageKey = "FileHistory." + provider.getClass().getName();
386	    if (treeHistoryProvider != null) {
387	      myDualView = new DualView(new TreeNodeOnVcsRevision(null, treeHistoryProvider.createTreeOn(myHistorySession.getRevisionList())),
388	                                columns, storageKey, myVcs.getProject());
389	    }
390	    else {
391	      myDualView = new DualView(new TreeNodeOnVcsRevision(null, wrapWithTreeElements(myHistorySession.getRevisionList())), columns,
392	                                storageKey, myVcs.getProject());
393	      myDualView.switchToTheFlatMode();
394	    }
395	    new TableSpeedSearch(myDualView.getFlatView()).setComparator(new SpeedSearchComparator(false));
396	    final TableLinkMouseListener listener = new TableLinkMouseListener();
397	    listener.installOn(myDualView.getFlatView());
398	    listener.installOn(myDualView.getTreeView());
399	    setEmptyText(CommonBundle.getLoadingTreeNodeText());
400	
401	    createDualView();
402	    if (isStaticEmbedded) {
403	      setIsStaticAndEmbedded(isStaticEmbedded);
404	    }
405	
406	    myPopupActions = createPopupActions();
407	
408	    myHistoryPanelRefresh = new AsynchConsumer<VcsHistorySession>() {
409	      public void finished() {
410	        if (treeHistoryProvider != null) {
411	          // scroll tree view to most recent change
412	          final TreeTableView treeView = myDualView.getTreeView();
413	          final int lastRow = treeView.getRowCount() - 1;
414	          if (lastRow >= 0) {
415	            treeView.scrollRectToVisible(treeView.getCellRect(lastRow, 0, true));
416	          }
417	        }
418	        myInRefresh = false;
419	        myTargetSelection = null;
420	
421	        mySplitter.revalidate();
422	        mySplitter.repaint();
423	      }
424	      public void consume(VcsHistorySession vcsHistorySession) {
425	        FileHistoryPanelImpl.this.refresh(vcsHistorySession);
426	      }
427	    };
428	
429	    // todo react to event?
430	    myUpdateAlarm.addRequest(new Runnable() {
431	      public void run() {
432	        if (myVcs.getProject().isDisposed()) {
433	          return;
434	        }
435	        boolean refresh = ApplicationManager.getApplication().isActive()
436	          && !myInRefresh
437	          && myHistorySession.shouldBeRefreshed();
438	
439	        myUpdateAlarm.cancelAllRequests();
440	        if (myUpdateAlarm.isDisposed()) return;
441	        myUpdateAlarm.addRequest(this, 20000);
442	
443	        if (refresh) {
444	          refreshImpl(true);
445	        }
446	      }
447	    }, 20000);
448	
449	    init();
450	
451	    chooseView();
452	  }
