454	  private void replaceTransferable() {
455	    final TransferHandler originalTransferHandler = myComments.getTransferHandler();
456	
457	    final TransferHandler newHandler = new TransferHandler("copy") {
458	      @Override
459	      public void exportAsDrag(final JComponent comp, final InputEvent e, final int action) {
460	        originalTransferHandler.exportAsDrag(comp, e, action);
461	      }
462	
463	      @Override
464	      public void exportToClipboard(final JComponent comp, final Clipboard clip, final int action) throws IllegalStateException {
465	        if ((action == COPY || action == MOVE)
466	                && (getSourceActions(comp) & action) != 0) {
467	
468	          String selectedText = myComments.getSelectedText();
469	          final Transferable t;
470	          if (selectedText == null) {
471	            t = new TextTransferable(myComments.getText(), myOriginalComment);
472	          }
473	          else {
474	            t = new TextTransferable(selectedText);
475	          }
476	          try {
477	            clip.setContents(t, null);
478	            exportDone(comp, t, action);
479	            return;
480	          }
481	          catch (IllegalStateException ise) {
482	            exportDone(comp, t, NONE);
483	            throw ise;
484	          }
485	        }
486	
487	        exportDone(comp, null, NONE);
488	      }
489	
490	      @Override
491	      public boolean importData(final JComponent comp, final Transferable t) {
492	        return originalTransferHandler.importData(comp, t);
493	      }
494	
495	      @Override
496	      public boolean canImport(final JComponent comp, final DataFlavor[] transferFlavors) {
497	        return originalTransferHandler.canImport(comp, transferFlavors);
498	      }
499	
500	      @Override
501	      public int getSourceActions(final JComponent c) {
502	        return originalTransferHandler.getSourceActions(c);
503	      }
504	
505	      @Override
506	      public Icon getVisualRepresentation(final Transferable t) {
507	        return originalTransferHandler.getVisualRepresentation(t);
508	      }
509	    };
510	
511	    myComments.setTransferHandler(newHandler);
512	  }
