514	  private DualViewColumnInfo[] createColumnList(Project project, VcsHistoryProvider provider, final VcsHistorySession session) {
515	    final VcsDependentHistoryComponents components = provider.getUICustomization(session, this);
516	    myAdditionalDetails = components.getDetailsComponent();
517	    myListener = components.getRevisionListener();
518	
519	    ArrayList<DualViewColumnInfo> columns = new ArrayList<DualViewColumnInfo>();
520	    columns.add(new RevisionColumnInfo(myRevisionsInOrderComparator));
521	    if (!provider.isDateOmittable()) columns.add(new DateColumnInfo());
522	    columns.add(new AuthorColumnInfo());
523	    columns.addAll(wrapAdditionalColumns(components.getColumns()));
524	    columns.add(new MessageColumnInfo(project));
525	    return columns.toArray(new DualViewColumnInfo[columns.size()]);
526	  }
527	
528	  private Collection<DualViewColumnInfo> wrapAdditionalColumns(ColumnInfo[] additionalColumns) {
529	    ArrayList<DualViewColumnInfo> result = new ArrayList<DualViewColumnInfo>();
530	    if (additionalColumns != null) {
531	      for (ColumnInfo additionalColumn : additionalColumns) {
532	        result.add(new MyColumnWrapper(additionalColumn));
533	      }
534	    }
535	    return result;
536	  }
