538	  private static List<TreeItem<VcsFileRevision>> wrapWithTreeElements(List<VcsFileRevision> revisions) {
539	    ArrayList<TreeItem<VcsFileRevision>> result = new ArrayList<TreeItem<VcsFileRevision>>();
540	    for (final VcsFileRevision revision : revisions) {
541	      result.add(new TreeItem<VcsFileRevision>(revision));
542	    }
543	    return result;
544	  }
