946	    private void getVersion(final VcsFileRevision revision) {
947	      final VirtualFile file = getVirtualFile();
948	      final Project project = myVcs.getProject();
949	
950	      new Task.Backgroundable(project, VcsBundle.message("show.diff.progress.title")) {
951	        @Override
952	        public void run(@NotNull ProgressIndicator indicator) {
953	          final LocalHistoryAction action = file != null ? startLocalHistoryAction(revision) : LocalHistoryAction.NULL;
954	          final byte[] revisionContent;
955	          try {
956	            revisionContent = VcsHistoryUtil.loadRevisionContent(revision);
957	          } catch (final IOException e) {
958	            LOG.info(e);
959	            ApplicationManager.getApplication().invokeLater(new Runnable() {
960	              @Override public void run() {
961	                Messages.showMessageDialog(VcsBundle.message("message.text.cannot.load.revision", e.getLocalizedMessage()),
962	                                           VcsBundle.message("message.title.get.revision.content"), Messages.getInformationIcon());
963	              }
964	            });
965	            return;
966	          } catch (final VcsException e) {
967	            LOG.info(e);
968	            ApplicationManager.getApplication().invokeLater(new Runnable() {
969	              @Override public void run() {
970	                Messages.showMessageDialog(VcsBundle.message("message.text.cannot.load.revision", e.getLocalizedMessage()),
971	                                           VcsBundle.message("message.title.get.revision.content"), Messages.getInformationIcon());
972	              }
973	            });
974	            return;
975	          } catch (ProcessCanceledException ex) {
976	            return;
977	          }
978	
979	          ApplicationManager.getApplication().invokeLater(new Runnable() {
980	            @Override
981	            public void run() {
982	              try {
983	                new WriteCommandAction.Simple(project) {
984	                  @Override
985	                  protected void run() throws Throwable {
986	                    if (file != null &&
987	                        !file.isWritable() &&
988	                        ReadonlyStatusHandler.getInstance(project).ensureFilesWritable(file).hasReadonlyFiles()) {
989	                      return;
990	                    }
991	
992	                    try {
993	                      write(revisionContent);
994	                    }
995	                    catch (IOException e) {
996	                      Messages.showMessageDialog(VcsBundle.message("message.text.cannot.save.content", e.getLocalizedMessage()),
997	                                                 VcsBundle.message("message.title.get.revision.content"), Messages.getErrorIcon());
998	                    }
999	                  }
1000	                }.execute();
1001	                if (file != null) {
1002	                  VcsDirtyScopeManager.getInstance(project).fileDirty(file);
1003	                }
1004	              }
1005	              finally {
1006	                action.finish();
1007	              }
1008	            }
1009	          });
1010	        }
1011	      }.queue();
1012	    }
