657	  private void showDifferences(final Project project, final VcsFileRevision revision1, final VcsFileRevision revision2) {
658	    new Task.Backgroundable(project, "Loading revisions to compare") {
659	      @Override
660	      public void run(@NotNull ProgressIndicator indicator) {
661	        VcsFileRevision left = revision1;
662	        VcsFileRevision right = revision2;
663	        if (VcsHistoryUtil.compare(revision1, revision2) > 0) {
664	          left = revision2;
665	          right = revision1;
666	        }
667	
668	        try {
669	          final String leftTitle = left.getRevisionNumber().asString() +
670	                                   (left instanceof CurrentRevision ? " (" + VcsBundle.message("diff.title.local") + ")" : "");
671	          final String rightTitle = right.getRevisionNumber().asString() +
672	                                    (right instanceof CurrentRevision ? " (" + VcsBundle.message("diff.title.local") + ")" : "");
673	          VcsHistoryUtil.showDiff(project, myFilePath, left, right, leftTitle, rightTitle);
674	        }
675	        catch (final VcsException e) {
676	          LOG.info(e);
677	          WaitForProgressToShow.runOrInvokeLaterAboveProgress(new Runnable() {
678	            public void run() {
679	              Messages.showErrorDialog(VcsBundle.message("message.text.cannot.show.differences", e.getLocalizedMessage()),
680	                                       VcsBundle.message("message.title.show.differences"));
681	            }
682	          }, null, project);
683	        }
684	        catch (IOException e) {
685	          LOG.info(e);
686	        }
687	        catch (ProcessCanceledException ex) {
688	          LOG.info(ex);
689	        }
690	      }
691	    }.queue();
692	  }
