1028	        @Override
1029	        public void run(@NotNull ProgressIndicator indicator) {
1030	          LocalHistoryAction action = file != null ? startLocalHistoryAction(revision) : LocalHistoryAction.NULL;
1031	          final byte[] revisionContent;
1032	          try {
1033	            revisionContent = VcsHistoryUtil.loadRevisionContent(revision);
1034	          } catch (final IOException e) {
1035	            LOG.info(e);
1036	            ApplicationManager.getApplication().invokeLater(new Runnable() {
1037	              @Override public void run() {
1038	                Messages.showMessageDialog(VcsBundle.message("message.text.cannot.load.revision", e.getLocalizedMessage()),
1039	                                           VcsBundle.message("message.title.get.revision.content"), Messages.getInformationIcon());
1040	              }
1041	            });
1042	            return;
1043	          } catch (final VcsException e) {
1044	            LOG.info(e);
1045	            ApplicationManager.getApplication().invokeLater(new Runnable() {
1046	              @Override public void run() {
1047	                Messages.showMessageDialog(VcsBundle.message("message.text.cannot.load.revision", e.getLocalizedMessage()),
1048	                                           VcsBundle.message("message.title.get.revision.content"), Messages.getInformationIcon());
1049	              }
1050	            });
1051	            return;
1052	          } catch (ProcessCanceledException ex) {
