1054	          }
1055	
1056	          try {
1057	            UIUtil.invokeAndWaitIfNeeded(new Runnable() {
1058	              @Override public void run() {
1059	                ApplicationManager.getApplication().runWriteAction(new Runnable() {
1060	                  public void run() {
1061	                    CommandProcessor.getInstance().executeCommand(project, new Runnable() {
1062	                      public void run() {
1063	                        if (file != null && !file.isWritable()) {
1064	                          if (ReadonlyStatusHandler.getInstance(project).ensureFilesWritable(file).hasReadonlyFiles()) {
