1074	                        }
1075	                      }
1076	                    }, createGetActionTitle(revision), null);
1077	                  }
1078	                });
1079	              }
1080	            });
1081	
1082	            if (file != null) {
1083	              VcsDirtyScopeManager.getInstance(project).fileDirty(file);
1084	            }
1085	          }
1086	          finally {
